	private static final String PREDICATE_QUERY = "SELECT ?ns (COUNT(*) AS ?statements) "
			+ "(COUNT(DISTINCT ?p) AS ?predicates) WHERE { ?s ?p ?o . "
			+ "BIND(REPLACE(STR(?p), \"[^/#]+$\", \"\") AS ?ns) } GROUP BY ?ns";
	private static final String DATATYPE_QUERY = "SELECT ?datatype (COUNT(*) AS ?literals) WHERE { "
			+ "?s ?p ?o . FILTER(isLiteral(?o)) BIND(DATATYPE(?o) AS ?datatype) } GROUP BY ?datatype";
