	private void verifyDecline(Alternative target, boolean missingBeforeQuote) throws Exception {
		Fixture fixture = new Fixture(target);
		try (fixture) {
			fixture.assertIndependentNativePreflight();
			fixture.genericOpens.set(0);
			if (missingBeforeQuote) {
				fixture.source.withdrawCapabilities();
			}

			Path recordingPath = dataDir.toPath().resolve(target + "-" + missingBeforeQuote + ".jfr");
			Outcome outcome;
			List<RecordedEvent> events;
			try (Recording recording = new Recording()) {
				recording.enable(EVENT).withThreshold(Duration.ZERO);
				recording.start();
				try (Capture capture = fixture.capture()) {
					assertThat(capture.targetProposal)
							.as("the compiled native candidate reaches the shared aggregate inventory")
							.isNotNull();
					if (missingBeforeQuote) {
						assertThat(capture.targetProposal.work.known())
								.as("withheld source capabilities produce no fabricated finite work quote")
								.isFalse();
					} else {
						assertThat(fixture.source.withdrawn.get())
								.as("the independently preflighted source remains available before withdrawal")
								.isFalse();
						fixture.source.withdrawCapabilities();
					}
					fixture.source.assertPrefixRunsUnavailable(capture.evaluation);
					outcome = capture.select();
				} finally {
					if (recording.getState() == RecordingState.RUNNING) {
						recording.stop();
					}
					recording.dump(recordingPath);
				}
			}
			events = RecordingFile.readAllEvents(recordingPath)
					.stream()
					.filter(event -> EVENT.equals(event.getEventType().getName()))
					.filter(event -> target.tag.equals(event.getString("strategy")))
					.toList();

			List<RecordedEvent> candidates = events.stream()
					.filter(event -> "CANDIDATE".equals(event.getString("phase")))
					.toList();
			List<RecordedEvent> attempts = events.stream()
					.filter(event -> "ATTEMPT".equals(event.getString("phase")))
					.toList();
			List<RecordedEvent> observations = events.stream()
					.filter(event -> "OBSERVATION".equals(event.getString("phase")))
					.toList();
			assertAll("a forced common-arbiter candidate must expose unavailable native work",
					() -> assertThat(candidates).as("the exact specialization was offered").isNotEmpty(),
					() -> assertThat(attempts).as("the forced specialization reached an actual opener").isNotEmpty(),
					() -> assertThat(attempts).allSatisfy(event -> assertThat(event.getString("status"))
							.as("an unavailable recipe must decline rather than publish generic work")
							.isEqualTo("DECLINED")),
					() -> assertThat(attempts).allSatisfy(event -> assertThat(event.getString("availabilityReason"))
							.as("the actual native opener reports why it declined")
							.isNotBlank()),
					() -> assertThat(observations)
							.as("a decline cannot produce an exhausted observation")
							.noneSatisfy(event -> assertThat(event.getString("status")).isEqualTo("EXHAUSTED")),
					() -> assertThat(observations).allSatisfy(event -> {
						assertThat(event.getString("status")).isEqualTo("DECLINED");
						assertThat(event.getLong("exactCompletedCount")).isZero();
					}),
					() -> assertThat(candidates).allSatisfy(event -> assertThat(event.getLong("exactCompletedCount"))
							.as("a fresh capability check cannot invent completed samples")
							.isZero()),
					() -> assertThat(outcome.failure)
							.as("the authoritative forced strategy reports its actual capability decline")
							.isNotNull()
							.hasMessageContaining("was offered and declined"),
					() -> assertThat(outcome.result).as("no hidden generic result escapes the selected native arm")
							.isNull(),
					() -> assertThat(fixture.genericOpens)
							.as("the specialized evaluateUnmeasured path never opens genericPrecompile")
							.hasValue(0));
		}
	}

